package ru.folio.notes;

import android.Manifest;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.media.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.*;

/** Foreground audio notes. Pausing the activity finalizes a recording rather than losing it. */
final class AudioStudio {
    static final int PERMISSION=42;final MainActivity a;MediaRecorder recorder;MediaPlayer player;Ink.Doc owner;Ink.Audio record;long started;boolean paused;long pauseAt,pausedMs;LinearLayout content;TextView clock;Studio.Sheet sheet;String playing="";
    AudioStudio(MainActivity a){this.a=a;}
    static String time(long ms){long seconds=Math.max(0,ms/1000);return String.format(Locale.ROOT,"%02d:%02d",seconds/60,seconds%60);}
    long elapsed(){return recorder==null?0:(paused?pauseAt:SystemClock.elapsedRealtime())-started-pausedMs;}
    Studio.Sheet show(){if(a.current==null)return null;content=a.column();fill();sheet=new Studio.Builder(a).anchor(a.editorHeader).width(410).contentHeight(390).setTitle("Аудиозаметки").setView(content).setPositiveButton("Готово",null).show();return sheet;}
    void fill(){if(content==null||a.current==null)return;content.removeAllViews();LinearLayout live=a.column();live.setBackground(Studio.surface(0xff1c1f27,20,a.getResources().getDisplayMetrics().density));a.pad(live,14,12);clock=a.text(recorder==null?"Сохраните голос рядом с мыслью":time(elapsed())+(paused?" · пауза":" · запись"),17,recorder==null?Studio.TEXT:0xffef9aab,true);live.addView(clock);View wave=new View(a){final Paint p=new Paint(3);protected void onDraw(Canvas c){p.setStrokeWidth(a.dp(3));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(recorder==null?Studio.MUTED:Studio.ACCENT);int amplitude=0;if(recorder!=null&&!paused)try{amplitude=recorder.getMaxAmplitude();}catch(Exception ignored){}float level=Math.min(1,amplitude/18000f);for(int i=0;i<32;i++){float x=(i+.5f)*getWidth()/32f,h=a.dp(2)+(float)Math.abs(Math.sin(i*.7+SystemClock.uptimeMillis()*.004))*getHeight()*.32f*level;c.drawLine(x,getHeight()/2f-h,x,getHeight()/2f+h,p);}if(recorder!=null&&hasWindowFocus()){clock.setText(time(elapsed())+(paused?" · пауза":" · запись"));postInvalidateDelayed(80);}}};wave.setContentDescription("Уровень микрофона");live.addView(wave,new LinearLayout.LayoutParams(-1,a.dp(62)));LinearLayout controls=a.row();
        if(recorder==null)controls.addView(Studio.button(a,"●  Записать",true,this::start));else {controls.addView(Studio.button(a,paused?"Продолжить":"Пауза",false,()->{try{if(paused){recorder.resume();pausedMs+=SystemClock.elapsedRealtime()-pauseAt;}else {recorder.pause();pauseAt=SystemClock.elapsedRealtime();}paused=!paused;fill();}catch(Exception e){a.error("Запись",e);}}));a.space(controls,8);controls.addView(Studio.button(a,"Сохранить",true,this::stop));}live.addView(controls);Studio.addCard(a,content,live);
        for(Ink.Audio audio:a.current.audio){LinearLayout row=Studio.row(a,"audio",audio.name,time(audio.duration)+(playing.equals(audio.file)?" · играет, нажмите для остановки":""),()->play(audio));a.addIcon(row,"more","Действия с записью",()->new Studio.Builder(a).setTitle(audio.name).setItems(new String[]{"Переименовать","К странице записи","Удалить запись"},(d,w)->{if(w==0)a.edit("Название записи","Название",audio.name,value->{audio.name=value;a.changed();fill();});if(w==1){for(int i=0;i<a.current.pages.size();i++)if(a.current.pages.get(i).id.equals(audio.page)){if(sheet!=null)sheet.dismiss();a.goPage(i);break;}}if(w==2)a.confirm("Удалить запись?","Она исчезнет из тетради. В ранее экспортированных копиях запись останется.",()->{if(player!=null){player.release();player=null;}a.current.audio.remove(audio);a.changed();fill();});}).show());Studio.addCard(a,content,row);}
    }
    void start(){if(a.current==null)return;if(a.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},PERMISSION);return;}try{if(player!=null){player.release();player=null;}owner=a.current;record=new Ink.Audio();record.file=Ink.id()+".m4a";record.page=owner.page().id;record.name=new SimpleDateFormat("d MMM · HH:mm",new Locale("ru")).format(new Date());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(96000);recorder.setOutputFile(a.store.asset(record.file).toString());recorder.setMaxDuration(1800000);recorder.setOnInfoListener((r,what,extra)->{if(what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED)stop();});recorder.prepare();recorder.start();started=SystemClock.elapsedRealtime();pausedMs=0;paused=false;fill();}catch(Exception e){if(recorder!=null){recorder.release();recorder=null;}a.error("Не удалось начать запись",e);}}
    void stop(){if(recorder==null)return;long duration=elapsed();boolean saved=false;try{recorder.stop();record.duration=duration;owner.audio.add(record);owner.modified=System.currentTimeMillis();a.persist(owner);if(a.current==owner)a.changed();saved=true;}catch(Exception e){a.toast("Запись слишком короткая или микрофон недоступен");}finally{recorder.release();recorder=null;if(!saved)try{a.store.asset(record.file).delete();}catch(IOException ignored){}owner=null;record=null;paused=false;fill();}}
    void play(Ink.Audio audio){try{if(player!=null){boolean same=playing.equals(audio.file);player.release();player=null;playing="";if(same){fill();return;}}player=new MediaPlayer();playing=audio.file;player.setDataSource(a.store.asset(audio.file).toString());player.setOnCompletionListener(p->{p.release();if(player==p)player=null;playing="";fill();});player.prepare();player.start();fill();a.toast("Воспроизведение: "+audio.name);}catch(Exception e){a.error("Запись недоступна",e);}}
    void pause(){stop();if(player!=null){player.release();player=null;}playing="";}
}
